#!/bin/bash
FILE="apps/android/app/src/main/java/ai/openclaw/app/ui/SettingsSheet.kt"

# 批量替换设置界面的字符串
sed -i 's/Text("Name", style = mobileCaption1, color = mobileTextSecondary)/Text(stringResource(R.string.name), style = mobileCaption1, color = mobileTextSecondary)/g' "$FILE"
