sed -i 's/Text("Camera", style = mobileHeadline)/Text(stringResource(R.string.camera), style = mobileHeadline)/g' "$FILE"
sed -i 's/Text("System Notifications", style = mobileHeadline)/Text(stringResource(R.string.system_notifications), style = mobileHeadline)/g' "$FILE"
sed -i 's/Text("Alerts and foreground service.", style = mobileCallout)/Text(stringResource(R.string.alerts_foreground), style = mobileCallout)/g' "$FILE"
sed -i 's/Text("Notification Listener Access", style = mobileHeadline)/Text(stringResource(R.string.notification_listener), style = mobileHeadline)/g' "$FILE"
sed -i 's/Text("SMS", style = mobileHeadline)/Text(stringResource(R.string.sms), style = mobileHeadline)/g' "$FILE"
