sed -i 's/Text("All packages except listed IDs are forwarded.", style = mobileCallout)/Text(stringResource(R.string.all_except_listed), style = mobileCallout)/g' "$FILE"
sed -i 's/Text("Search apps", style = mobileCaption1, color = mobileTextSecondary)/Text(stringResource(R.string.search_apps), style = mobileCaption1, color = mobileTextSecondary)/g' "$FILE"
sed -i 's/Text("Show System Apps", style = mobileHeadline)/Text(stringResource(R.string.show_system_apps), style = mobileHeadline)/g' "$FILE"
