sed -i 's/Text("Search and add contacts.", style = mobileCallout)/Text(stringResource(R.string.search_add_contacts), style = mobileCallout)/g' "$FILE"
sed -i 's/Text("Calendar", style = mobileHeadline)/Text(stringResource(R.string.calendar), style = mobileHeadline)/g' "$FILE"
sed -i 's/Text("Read and create events.", style = mobileCallout)/Text(stringResource(R.string.read_create_events), style = mobileCallout)/g' "$FILE"
sed -i 's/Text("Call Log", style = mobileHeadline)/Text(stringResource(R.string.call_log), style = mobileHeadline)/g' "$FILE"
sed -i 's/Text("Search recent call history.", style = mobileCallout)/Text(stringResource(R.string.search_call_history), style = mobileCallout)/g' "$FILE"
sed -i 's/Text("Motion", style = mobileHeadline)/Text(stringResource(R.string.motion), style = mobileHeadline)/g' "$FILE"
sed -i 's/Text("Track steps and activity.", style = mobileCallout)/Text(stringResource(R.string.track_steps), style = mobileCallout)/g' "$FILE"

echo "✓ SettingsSheet.kt 汉化完成！"
